using System.Text;using Microsoft.EntityFrameworkCore;using RetailShop.Application.Common;using RetailShop.Application.Finance;using RetailShop.Domain.Finance;using RetailShop.Infrastructure.Persistence;
namespace RetailShop.Infrastructure.Finance;
internal sealed class FinanceReportingService(RetailShopDbContext db):IFinanceReportingService
{
 public async Task<OperationResult<GeneralLedgerReport>> GeneralLedgerAsync(Guid accountId,DateOnly from,DateOnly to,int page,int size,CancellationToken ct=default){if(to<from)return OperationResult<GeneralLedgerReport>.Failure("End date cannot precede start date.");page=Math.Max(page,1);size=Math.Clamp(size,1,100);var a=await db.Accounts.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==accountId,ct);if(a is null)return OperationResult<GeneralLedgerReport>.Failure("Account not found.");var sign=a.NormalBalance==NormalBalance.Debit?1m:-1m;var opening=await db.JournalLines.Where(x=>x.AccountId==accountId&&x.JournalEntry.BusinessDate<from).SumAsync(x=>(decimal?)(x.Debit-x.Credit),ct)??0;var q=db.JournalLines.AsNoTracking().Where(x=>x.AccountId==accountId&&x.JournalEntry.BusinessDate>=from&&x.JournalEntry.BusinessDate<=to).OrderBy(x=>x.JournalEntry.BusinessDate).ThenBy(x=>x.JournalEntry.PostedOn).ThenBy(x=>x.Id);var count=await q.CountAsync(ct);var before=await q.Take((page-1)*size).SumAsync(x=>(decimal?)(x.Debit-x.Credit),ct)??0;var raw=await q.Skip((page-1)*size).Take(size).Select(x=>new{x.JournalEntryId,x.JournalEntry.BusinessDate,x.JournalEntry.Number,x.JournalEntry.SourceType,x.JournalEntry.SourceId,x.JournalEntry.Description,x.Debit,x.Credit}).ToArrayAsync(ct);var running=(opening+before)*sign;var rows=raw.Select(x=>{running+=(x.Debit-x.Credit)*sign;return new LedgerRow(x.JournalEntryId,x.BusinessDate,x.Number,x.SourceType,x.SourceId,x.Description,x.Debit,x.Credit,running);}).ToArray();var period=await q.SumAsync(x=>(decimal?)(x.Debit-x.Credit),ct)??0;return OperationResult<GeneralLedgerReport>.Success(new(accountId,a.Code,a.Name,a.NormalBalance,from,to,opening*sign,(opening+period)*sign,new(rows,page,size,count),await Provisional(ct)));}
 public async Task<OperationResult<TrialBalanceReport>> TrialBalanceAsync(DateOnly from,DateOnly to,CancellationToken ct=default){if(to<from)return OperationResult<TrialBalanceReport>.Failure("End date cannot precede start date.");var rows=await db.Accounts.AsNoTracking().Where(a=>a.Kind==AccountKind.Posting&&a.HasPostings).OrderBy(a=>a.Code).Select(a=>new{a.Id,a.Code,a.Name,a.Type,a.IsActive,Opening=db.JournalLines.Where(l=>l.AccountId==a.Id&&l.JournalEntry.BusinessDate<from).Sum(l=>(decimal?)(l.Debit-l.Credit))??0,Debit=db.JournalLines.Where(l=>l.AccountId==a.Id&&l.JournalEntry.BusinessDate>=from&&l.JournalEntry.BusinessDate<=to).Sum(l=>(decimal?)l.Debit)??0,Credit=db.JournalLines.Where(l=>l.AccountId==a.Id&&l.JournalEntry.BusinessDate>=from&&l.JournalEntry.BusinessDate<=to).Sum(l=>(decimal?)l.Credit)??0}).ToArrayAsync(ct);var items=rows.Select(x=>{var close=x.Opening+x.Debit-x.Credit;return new TrialBalanceRow(x.Id,x.Code,x.Name,x.Type,x.IsActive,Math.Max(x.Opening,0),Math.Max(-x.Opening,0),x.Debit,x.Credit,Math.Max(close,0),Math.Max(-close,0));}).ToArray();var td=items.Sum(x=>x.ClosingDebit);var tc=items.Sum(x=>x.ClosingCredit);return OperationResult<TrialBalanceReport>.Success(new(from,to,items,td,tc,td-tc,await Provisional(ct)));}
 public async Task<OperationResult<ProfitLossReport>> ProfitLossAsync(DateOnly from,DateOnly to,CancellationToken ct=default){var previousFrom=from.AddDays(-(to.DayNumber-from.DayNumber+1));var rows=await StatementRows([AccountType.Income,AccountType.Expense],from,to,previousFrom,from.AddDays(-1),ct);var income=rows.Where(x=>x.Type==AccountType.Income).Select(x=>x.Row with{Current=-x.Row.Current,Previous=-x.Row.Previous}).ToArray();var expense=rows.Where(x=>x.Type==AccountType.Expense).Select(x=>x.Row).ToArray();var revenue=await Mapped(SystemAccountKeys.SalesRevenue,from,to,ct)*-1;var returns=await Mapped(SystemAccountKeys.SalesReturns,from,to,ct);var cogs=await Mapped(SystemAccountKeys.CostOfGoodsSold,from,to,ct);var op=expense.Sum(x=>x.Current)-cogs;return OperationResult<ProfitLossReport>.Success(new(from,to,income,expense,revenue,returns,revenue-returns,cogs,revenue-returns-cogs,op,income.Sum(x=>x.Current)-expense.Sum(x=>x.Current),await Provisional(ct)));}
 public async Task<OperationResult<BalanceSheetReport>> BalanceSheetAsync(DateOnly asOf,CancellationToken ct=default){var rows=await StatementRows([AccountType.Asset,AccountType.Liability,AccountType.Equity],DateOnly.MinValue,asOf,DateOnly.MinValue,DateOnly.MinValue,ct);StatementRow[] Pick(AccountType t)=>rows.Where(x=>x.Type==t).Select(x=>t==AccountType.Asset?x.Row:x.Row with{Current=-x.Row.Current}).ToArray();var assets=Pick(AccountType.Asset);var liabilities=Pick(AccountType.Liability);var equity=Pick(AccountType.Equity);var earnings=-(await db.JournalLines.Where(x=>(x.Account.Type==AccountType.Income||x.Account.Type==AccountType.Expense)&&x.JournalEntry.BusinessDate<=asOf).SumAsync(x=>(decimal?)(x.Debit-x.Credit),ct)??0);var ta=assets.Sum(x=>x.Current);var tl=liabilities.Sum(x=>x.Current);var te=equity.Sum(x=>x.Current)+earnings;return OperationResult<BalanceSheetReport>.Success(new(asOf,assets,liabilities,equity,ta,tl,te,earnings,ta-tl-te,await Provisional(ct)));}
 public async Task<OperationResult<CashFlowReport>> CashFlowAsync(DateOnly from,DateOnly to,CancellationToken ct=default){var cashIds=await db.FinancialAccounts.Where(x=>x.IsActive).Select(x=>x.AccountId).Distinct().ToArrayAsync(ct);var begin=await db.JournalLines.Where(x=>cashIds.Contains(x.AccountId)&&x.JournalEntry.BusinessDate<from).SumAsync(x=>(decimal?)(x.Debit-x.Credit),ct)??0;var moves=await db.JournalLines.Where(x=>cashIds.Contains(x.AccountId)&&x.JournalEntry.BusinessDate>=from&&x.JournalEntry.BusinessDate<=to&&x.JournalEntry.SourceType!="FundTransfer").GroupBy(x=>x.JournalEntry.SourceType).Select(g=>new{Source=g.Key,Amount=g.Sum(x=>x.Debit-x.Credit)}).ToArrayAsync(ct);var known=new[]{"Sale","SalePayment","CustomerReceipt","Purchase","PurchasePayment","ExpenseVoucher","SalesReturn","PurchaseReturn"};var operating=moves.Where(x=>known.Contains(x.Source)).Sum(x=>x.Amount);var unknown=moves.Where(x=>!known.Contains(x.Source)).Sum(x=>x.Amount);var net=moves.Sum(x=>x.Amount);return OperationResult<CashFlowReport>.Success(new(from,to,begin,operating,0,0,unknown,net,begin+net,unknown==0,await Provisional(ct)));}
 public async Task<OperationResult<FinanceDashboardReport>> DashboardAsync(DateOnly from,DateOnly to,CancellationToken ct=default){async Task<decimal> Key(string k)=>await Mapped(k,DateOnly.MinValue,to,ct);var pnl=(await ProfitLossAsync(from,to,ct)).Value!;return OperationResult<FinanceDashboardReport>.Success(new(from,to,await Key(SystemAccountKeys.CashInHand),await Key(SystemAccountKeys.Bank),await Key(SystemAccountKeys.Bkash),await Key(SystemAccountKeys.CardClearing),await Key(SystemAccountKeys.CustomerReceivables),-await Key(SystemAccountKeys.SupplierPayables),await Key(SystemAccountKeys.InventoryAsset),pnl.GrossRevenue,pnl.CostOfGoodsSold,pnl.GrossProfit,pnl.OperatingExpenses,pnl.NetProfit,await Provisional(ct)));}
 public async Task<OperationResult<FinanceCsvFile>> ExportTrialBalanceAsync(DateOnly from,DateOnly to,CancellationToken ct=default){var r=await TrialBalanceAsync(from,to,ct);if(!r.Succeeded)return OperationResult<FinanceCsvFile>.Failure(r.Errors);var b=new StringBuilder("Account Code,Account Name,Opening Debit,Opening Credit,Period Debit,Period Credit,Closing Debit,Closing Credit\r\n");foreach(var x in r.Value!.Rows)b.AppendLine($"{Csv(x.Code)},{Csv(x.Name)},{x.OpeningDebit},{x.OpeningCredit},{x.PeriodDebit},{x.PeriodCredit},{x.ClosingDebit},{x.ClosingCredit}");b.AppendLine($"TOTAL,,,,,,{r.Value.TotalDebit},{r.Value.TotalCredit}");return OperationResult<FinanceCsvFile>.Success(new($"trial-balance-{from:yyyyMMdd}-{to:yyyyMMdd}.csv","text/csv",Encoding.UTF8.GetBytes(b.ToString())));}
 private async Task<(AccountType Type,StatementRow Row)[]> StatementRows(AccountType[] types,DateOnly from,DateOnly to,DateOnly pf,DateOnly pt,CancellationToken ct)=>await db.Accounts.Where(a=>a.Kind==AccountKind.Posting&&types.Contains(a.Type)).OrderBy(a=>a.Code).Select(a=>new ValueTuple<AccountType,StatementRow>(a.Type,new(a.Id,a.Code,a.Name,db.JournalLines.Where(l=>l.AccountId==a.Id&&l.JournalEntry.BusinessDate>=from&&l.JournalEntry.BusinessDate<=to).Sum(l=>(decimal?)(l.Debit-l.Credit))??0,pt>pf?(db.JournalLines.Where(l=>l.AccountId==a.Id&&l.JournalEntry.BusinessDate>=pf&&l.JournalEntry.BusinessDate<=pt).Sum(l=>(decimal?)(l.Debit-l.Credit))??0):0))).ToArrayAsync(ct);
 private async Task<decimal> Mapped(string key,DateOnly from,DateOnly to,CancellationToken ct){var id=await db.AccountMappings.Where(x=>x.Type==AccountMappingType.System&&x.Key==key&&x.IsActive).Select(x=>(Guid?)x.AccountId).SingleOrDefaultAsync(ct);return id.HasValue?await db.JournalLines.Where(x=>x.AccountId==id&&x.JournalEntry.BusinessDate>=from&&x.JournalEntry.BusinessDate<=to).SumAsync(x=>(decimal?)(x.Debit-x.Credit),ct)??0:0;}
 private async Task<bool> Provisional(CancellationToken ct){var a=await db.FinanceActivations.AsNoTracking().SingleAsync(ct);return !a.AutomaticPostingEnabled||!a.OpeningBalancesApproved;}
 private static string Csv(string v)=>$"\"{v.Replace("\"","\"\"")}\"";
}
